    if not isinstance(pattern, str) or not pattern:
        raise BudgetError("invalid budget pattern %r: write an account path such as Expenses:Food" % (pattern,))
    for seg in pattern.split(":"):
        if seg != "*" and not _SEGMENT.fullmatch(seg):
            raise BudgetError("invalid budget pattern '%s': bad segment '%s'" % (pattern, seg))


@dataclass(frozen=True)
class Budget:
    pattern: str
    period_kind: str
    amount: Money
    start: date

    def __post_init__(self):
        _check_pattern(self.pattern)
        if not isinstance(self.period_kind, str) or self.period_kind not in _KINDS:
            raise BudgetError("invalid period kind %r: use month, quarter or year" % (self.period_kind,))
        if not isinstance(self.amount, Money):
            raise BudgetError("budget amount must be money, not %r" % (self.amount,))
        if self.amount.minor <= 0:
            raise BudgetError("budget amount must be greater than zero, not %s" % (self.amount,))
        if not is_date(self.start):
            raise BudgetError("budget start must be a date, not %r" % (self.start,))

    def matches(self, account):
        """True when the account is an expense account named by the pattern or below it."""
        segs = account.split(":")
        if segs[0] != "Expenses":
            return False
        pat = self.pattern.split(":")
        if len(segs) < len(pat):
            return False
        return all(p == "*" or p == s for p, s in zip(pat, segs))


