class Recurring:
    __slots__ = ("_name", "_schedule", "_template", "_start", "_end", "_count")

    def __init__(self, name, schedule, template, start, end=None, count=None):
        if not isinstance(name, str) or not _NAME.fullmatch(name):
            raise RecurringError("invalid name %r: use letters, digits, - and _, not starting with - or _" % (name,))
        if isinstance(schedule, str):
            schedule = parse_schedule(schedule)
        elif not isinstance(schedule, Schedule):
            raise RecurringError("schedule must be a Schedule or text, not %r" % (schedule,))
        if not isinstance(template, Transaction):
            raise RecurringError("template must be a Transaction, not %r" % (template,))
        if not is_date(start):
            raise RecurringError("start must be a date, not %r" % (start,))
        if end is not None:
            if not is_date(end):
                raise RecurringError("end must be a date, not %r" % (end,))
            if end < start:
                raise RecurringError("end %s is before start %s" % (format_date(end), format_date(start)))
        if count is not None and (not _is_int(count) or count < 1):
            raise RecurringError("count must be a whole number of at least 1, not %r" % (count,))
        for attr, value in (("_name", name), ("_schedule", schedule), ("_template", template),
                            ("_start", start), ("_end", end), ("_count", count)):
            object.__setattr__(self, attr, value)

    def __setattr__(self, name, value):
        raise AttributeError("Recurring is immutable")

    name = property(lambda self: self._name)
    schedule = property(lambda self: self._schedule)
    template = property(lambda self: self._template)
    start = property(lambda self: self._start)
    end = property(lambda self: self._end)
    count = property(lambda self: self._count)

    def _fields(self):
        return (self._name, self._schedule, self._template, self._start, self._end, self._count)

    def __eq__(self, other):
        return isinstance(other, Recurring) and self._fields() == other._fields()

    def __ne__(self, other):
        return not self == other

    __hash__ = None

    def __repr__(self):
        return "Recurring(%r, %r)" % (self._name, str(self._schedule))


def _series(rec, start):
    """Dates of the series on or after ``start`` (never before rec.start), honouring end and count."""
    first = max(start, rec.start) if rec.count is None else rec.start
    produced = 0
    for d in rec.schedule._dates_from(first):
        if rec.end is not None and d > rec.end:
            return
        if rec.count is not None and produced >= rec.count:
            return
        produced += 1
        if d >= start:
            yield d


def occurrences(rec, start, end):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(start) or not is_date(end):
        raise RecurringError("occurrences needs two dates")
    out = []
    if end < start:
        return out
    for d in _series(rec, start):
        if d > end:
            break
        out.append(d)
    return out


def next_occurrence(rec, after):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(after):
        raise RecurringError("after must be a date, not %r" % (after,))
    if after >= date.max:
        return None
    for d in _series(rec, after + timedelta(days=1)):
        return d
    return None


def instantiate(rec, on):
    if not isinstance(rec, Recurring):
        raise RecurringError("not a recurring item: %r" % (rec,))
    if not is_date(on):
        raise RecurringError("on must be a date, not %r" % (on,))
    t = rec.template
    tags = tuple(sorted(set(t.tags) | {"recurring"}))
    return Transaction(on, t.payee, t.narration, list(t.postings), tags, t.flag, None)


def expand(recs, start, end):
    recs = list(recs)
    found = []
    for position, rec in enumerate(recs):
        if not isinstance(rec, Recurring):
            raise RecurringError("not a recurring item: %r" % (rec,))
        for d in occurrences(rec, start, end):
            found.append((d, rec.name, position))
    found.sort()
    return [instantiate(recs[position], d) for d, _, position in found]
