def _is_int(value):
    return isinstance(value, int) and not isinstance(value, bool)


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero (d > 0)."""
    if not _is_int(n) or not _is_int(d):
        raise MoneyError("round_div needs two integers")
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, not %d" % d)
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def format_minor(minor, cur):
    exponent = currency(cur).exponent
    if not _is_int(minor):
        raise MoneyError("minor units must be an integer, not %r" % (minor,))
    digits = str(abs(minor))
    if exponent:
        digits = digits.rjust(exponent + 1, "0")
        digits = digits[:-exponent] + "." + digits[-exponent:]
    return "-" + digits if minor < 0 else digits


_AMOUNT = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, cur):
    exponent = currency(cur).exponent
    if not isinstance(text, str):
        raise MoneyError("invalid amount '%s': not text" % (text,))
    m = _AMOUNT.fullmatch(text)
    if m is None:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.group(1), m.group(2), m.group(3)
    if frac is not None and len(frac) > exponent:
        raise MoneyError("invalid amount '%s': %s has %d decimals" % (text, cur, exponent))
    minor = int(whole + (frac or "").ljust(exponent, "0"))
    return -minor if sign == "-" else minor


