"""Shared helpers for the web API tests: a server in a thread on a temp book, a tiny HTTP client."""
import http.client
import io
import json
import os
import shutil
import socket
import sys
import tempfile
import threading
import unittest
from datetime import date

from tallybook.api.server import make_server
from tallybook.storage import Store

TODAY = date(2024, 6, 15)
JSON_HEADERS = {"Content-Type": "application/json"}

PROFILE = """\
date_column = Date
payee_column = Payee
amount_column = Amount
currency = USD
account = Assets:Bank
default_account = Expenses:Misc
"""


class Resp:
    def __init__(self, status, headers, body):
        self.status = status
        self.headers = headers  # lower-case names
        self.body = body

    @property
    def text(self):
        return self.body.decode("utf-8")

    def json(self):
        return json.loads(self.body.decode("utf-8"))

    def header(self, name):
        return self.headers.get(name.lower())


class ApiTestCase(unittest.TestCase):
    """One fresh book and one running server per test; nothing may reach stdout or stderr."""

    today = TODAY

    def setUp(self):
        self._real_out, self._real_err = sys.stdout, sys.stderr
        self.out, self.err = io.StringIO(), io.StringIO()
        sys.stdout, sys.stderr = self.out, self.err
        self.tmp = tempfile.mkdtemp(prefix="tallybook-api-")
        self.db = os.path.join(self.tmp, "book.db")
        Store.open(self.db, create=True).close()
        self.server = make_server(self.db, "127.0.0.1", 0, self.today)
        self.port = self.server.server_address[1]
        self.thread = threading.Thread(target=self.server.serve_forever, kwargs={"poll_interval": 0.05},
                                       daemon=True)
        self.thread.start()

    def tearDown(self):
        self.server.shutdown()
        self.server.server_close()
        self.thread.join(5)
        sys.stdout, sys.stderr = self._real_out, self._real_err
        shutil.rmtree(self.tmp, ignore_errors=True)
        self.assertEqual(self.out.getvalue(), "", "something was printed on stdout")
        self.assertEqual(self.err.getvalue(), "", "something was printed on stderr")

    # -- the book ------------------------------------------------------------
    def store(self):
        return Store.open(self.db)

    def seed(self):
        """Accounts and three transactions through the library."""
        from tests.helpers_liba import tx
        with self.store() as s:
            s.add_account("Assets:Bank", currency="USD")
            s.add_account("Assets:Cash", currency="USD")
            s.add_account("Expenses:Food")
            s.add_account("Income:Salary")
            s.add_transaction(tx("2024-03-01", "Employer", [("Assets:Bank", "2500.00 USD"),
                                                            ("Income:Salary", "-2500.00 USD")]))
            s.add_transaction(tx("2024-03-02", "Bakery", [("Expenses:Food", "12.50 USD"),
                                                          ("Assets:Cash", "-12.50 USD")], tags=["lunch"]))
            s.add_transaction(tx("2024-04-05", "Market", [("Expenses:Food", "40.00 USD"),
                                                          ("Assets:Bank", "-40.00 USD")]))

    # -- requests ------------------------------------------------------------
    def call(self, method, path, body=None, headers=None, json_body=True):
        """``body`` is JSON-encoded unless it is bytes/str (or json_body is False)."""
        hdrs = dict(headers or {})
        data = body
        if body is not None and not isinstance(body, (bytes, str)) and json_body:
            data = json.dumps(body).encode("utf-8")
            hdrs.setdefault("Content-Type", "application/json")
        elif isinstance(body, str):
            data = body.encode("utf-8")
        conn = http.client.HTTPConnection("127.0.0.1", self.port, timeout=20)
        try:
            conn.request(method, path, body=data, headers=hdrs)
